import sys
from collections import deque

def bfs(table, n, m, start):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[[False] * 4 for _ in range(m)] for _ in range(n)]
    queue = deque([(*start, 0)])
    visited[start[0]][start[1]][0] = True
    count = 0
    while queue:
        x, y, step = queue.popleft()
        if step == 4:
            count += 1
            step = 0
        next_char = 'DIMA'[step]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and table[nx][ny] == next_char and not visited[nx][ny][step]:
                if step == 3 and visited[nx][ny][0]:
                    return float('inf')
                visited[nx][ny][step] = True
                queue.append((nx, ny, step + 1))
    return count

n, m = map(int, sys.stdin.readline().split())
table = [sys.stdin.readline().strip() for _ in range(n)]

max_dima_count = 0
for i in range(n):
    for j in range(m):
        if table[i][j] == 'D':
            dima_count = bfs(table, n, m, (i, j))
            if dima_count == float('inf'):
                print("Poor Inna!")
                exit(0)
            max_dima_count = max(max_dima_count, dima_count)

if max_dima_count == 0:
    print("Poor Dima!")
else:
    print(max_dima_count)
